<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class AnalyticsController extends Controller { public function store(Request $r) { $d=$r->validate(['session_token'=>['nullable','uuid'],'path'=>['required','string','max:255'],'event_type'=>['nullable','in:page_view,product_view,add_to_cart,checkout_start,order_created'],'metadata'=>['nullable','array']]); $token=$d['session_token']??(string)Str::uuid(); $s=DB::table('visitor_sessions')->where('token',$token)->first(); if(!$s){$id=DB::table('visitor_sessions')->insertGetId(['token'=>$token,'referrer'=>substr((string)$r->header('Referer'),0,255),'user_agent_hash'=>hash('sha256',(string)$r->userAgent()),'last_seen_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}else{$id=$s->id;DB::table('visitor_sessions')->where('id',$id)->update(['last_seen_at'=>now(),'updated_at'=>now()]);} DB::table('page_views')->insert(['visitor_session_id'=>$id,'path'=>$d['path'],'event_type'=>$d['event_type']??'page_view','metadata'=>isset($d['metadata'])?json_encode($d['metadata']):null,'created_at'=>now(),'updated_at'=>now()]); return response()->json(['data'=>['session_token'=>$token]],201); } }
